// src/app/api/fetch_trainer_images/route.js

import { S3Client, GetObjectCommand } from '@aws-sdk/client-s3';

// Load environment variables using your .env.local variable names
const REGION = 'auto'; // Cloudflare R2 uses 'auto'
const ENDPOINT = process.env.R2_ENDPOINT;
const ACCESS_KEY_ID = process.env.R2_ACCESS_KEY_ID;
const SECRET_ACCESS_KEY = process.env.R2_SECRET_ACCESS_KEY;
const BUCKET_NAME = process.env.R2_BUCKET;
// Not used directly, but available if you need it
const ACCOUNT_ID = process.env.R2_ACCOUNT_ID;

// Helper to check if all required variables are present
function hasValidEnv() {
  return (
    ENDPOINT &&
    ACCESS_KEY_ID &&
    SECRET_ACCESS_KEY &&
    BUCKET_NAME
  );
}

export async function GET(request) {
  if (!hasValidEnv()) {
    return new Response(
      'Server configuration error: One or more required Cloudflare R2 environment variables are missing. Please check .env.local and restart the server.',
      { status: 500 }
    );
  }

  try {
    const { searchParams } = new URL(request.url);
    const trainer_id = searchParams.get('trainer_id');
    if (!trainer_id) {
      return new Response('Missing trainer_id', { status: 400 });
    }

    const s3Client = new S3Client({
      region: REGION,
      endpoint: ENDPOINT,
      credentials: {
        accessKeyId: ACCESS_KEY_ID,
        secretAccessKey: SECRET_ACCESS_KEY,
      },
    });

    const getObjectParams = {
      Bucket: BUCKET_NAME,
      Key: `trainers/${trainer_id}.png`,
    };

    const command = new GetObjectCommand(getObjectParams);

    // Fetch image from R2
    const response = await s3Client.send(command);

    // Stream/buffer the image
    const stream = response.Body;
    const chunks = [];
    for await (const chunk of stream) {
      chunks.push(chunk);
    }
    const imageBuffer = Buffer.concat(chunks);

    return new Response(imageBuffer, {
      status: 200,
      headers: {
        'Content-Type': 'image/png',
        'Cache-Control': 'public, max-age=3600',
      },
    });

  } catch (error) {
    console.error('Error fetching image:', error);
    if (error.name === 'NoSuchKey') {
      return new Response('Image not found', { status: 404 });
    }
    return new Response('Internal Server Error', { status: 500 });
  }
}
